r-reviews .sr-product-info h4{font-size:12px;font-weight:600;line-height:1.5;overflow-wrap:anywhere;margin:2px 0}.seller-reviews .sr-group-label{display:block;color:#839189;font-size:10px;font-weight:600;letter-spacing:.6px;text-transform:uppercase}.seller-reviews .sr-variant{font-size:11px;color:#7b8982;margin:4px 0 0;overflow-wrap:anywhere}.seller-reviews .sr-options{display:flex;gap:5px 12px;flex-wrap:wrap;margin:4px 0 0;font-size:10px;color:#7b8982;overflow-wrap:anywhere}.seller-reviews .sr-options div{display:flex;gap:4px;max-width:100%;flex-wrap:wrap}.seller-reviews .sr-options dt:after{content:':'}.seller-reviews .sr-options dd{margin:0;overflow-wrap:anywhere}
