ips:empty{margin:0 0 14px}.seller-reviews .sr-filter-chips a{padding:4px 9px;border:1px solid #dde6e1;border-radius:18px;background:white;font-size:11px;color:#52635b;max-width:100%;overflow-wrap:anywhere}.seller-reviews .sr-filter-chips .sr-clear-filters{background:transparent;border:0;color:#1f6f5b}.seller-reviews .sr-secondary-button{background:white;color:#52635b;border-color:#dde6e1;padding:5px 9px;margin-top:7px}.seller-reviews #reviewProductResults{list-style:none;border:1px solid #dde6e1;border-radius:9px;margin:6px 0;padding:4px;max-height:160px;overflow:auto}.seller-reviews #reviewProductResults button{width:100%;text-align:left;background:white;color:#34483f;border:0;white-space:normal;overflow-wrap:anywhere}.seller-reviews #reviewProductResults button:hover{background:#eef5f1}
